contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(amount > 0);
        require(loanToCollateral > 0);
        require(duration > 0);
        require(interest > 0);

        uint256 reqId = c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;
        c.clearRequest(reqId, false, false); if (__ESBMC_reverted()) return;

        assert(c.isActive(reqId) == false);
    }
}

