// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) internal {
        vm.assume(amount > 0);
        vm.assume(loanToCollateral > 0);
        vm.assume(duration > 0);
        vm.assume(interest > 0);
        uint256 reqId;
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 __r) { reqId = __r; } catch { return; }
        try c.clearRequest(reqId, false, false) {} catch { return; }
        assertTrue(c.isActive(reqId) == false);
    }

    function testFuzz_run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        _run(amount, interest, loanToCollateral, duration);
    }

    receive() external payable {}
}
